@Test
public void practice_priorityQueue_insertAll() {
    ArrayListMinPQ<Integer> pq = new ArrayListMinPQ<>();
    pq.insertAll(List.of(5, 2, 8));
    assertEquals(3, pq.size());
    assertEquals(Integer.valueOf(2), pq.findMin());
    points += 1;
}

@Test
public void practice_priorityQueue_toSortedList() {
    ArrayListMinPQ<Integer> pq = new ArrayListMinPQ<>();
    pq.insert(7);
    pq.insert(3);
    pq.insert(5);
    List<Integer> sorted = pq.toSortedList();
    assertEquals(List.of(3, 5, 7), sorted);
    assertEquals(3, pq.size());
    points += 1;
}

@Test
public void practice_binarySearch_leftmostOccurrence() {
    int[] arr = {1, 3, 3, 3, 7};
    assertEquals(1, EfficientSearch.binarySearchLeft(arr, 3));
    assertEquals(-1, EfficientSearch.binarySearchLeft(arr, 4));
}

@Test
public void practice_euclid_lcm() {
    assertEquals(36, Euclid.lcm(12, 18));
    assertEquals(12, Euclid.lcm(4, 12));
    points += 1;
}

@Test
public void practice_ngramCounting_mostFrequent() {
    Map<String, Integer> counts = new HashMap<>();
    counts.put("ab", 3);
    counts.put("cd", 5);
    counts.put("ef", 1);
    assertEquals("cd", NGramCounting.mostFrequentNGram(counts));
    points += 2;
}

@Test
public void practice_comparable_findMinTriangle() {
    Triangle t1 = new Triangle(3, 4, 5);
    Triangle t2 = new Triangle(1, 2, 3);
    Triangle t3 = new Triangle(5, 6, 7);
    List<Triangle> triangles = Arrays.asList(t1, t2, t3);
    assertEquals(t2, ShapeUtils.findMin(triangles));
    points += 2;
}

@Test
public void practice_sortedLinkedList_contains() {
    SortedLinkedList<Integer> list = new SortedLinkedList<>();
    list.add(3);
    list.add(1);
    list.add(5);
    assertTrue(list.contains(3));
    assertFalse(list.contains(4));
    points += 2;
}
